const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1], s = tok[2];
const adj = Array.from({ length: n + 1 }, () => []);
const diff = new Array(n + 1).fill(0);
for (let i = 0; i < m; i++) {
  const u = tok[3 + 2 * i], v = tok[4 + 2 * i];
  adj[u].push(v);
  diff[u]++;
  diff[v]--;
}
const plus = [], minus = [];
let bad = false;
for (let v = 1; v <= n; v++) {
  if (diff[v] === 1) plus.push(v);
  else if (diff[v] === -1) minus.push(v);
  else if (diff[v] !== 0) bad = true;
}
if (bad || ((plus.length || minus.length) && !(plus.length === 1 && minus.length === 1 && plus[0] === s))) {
  console.log('-1');
} else {
  for (const lst of adj) lst.sort((a, b) => b - a);
  const stack = [s], path = [];
  while (stack.length) {
    const v = stack[stack.length - 1];
    if (adj[v].length) stack.push(adj[v].pop());
    else path.push(stack.pop());
  }
  path.reverse();
  console.log(path.length === m + 1 ? path.join(' ') : '-1');
}

