import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedInputStream(System.in));
        st.nextToken(); int n = (int) st.nval;
        st.nextToken(); int m = (int) st.nval;
        st.nextToken(); int s = (int) st.nval;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        int[] diff = new int[n + 1];
        for (int i = 0; i < m; i++) {
            st.nextToken(); int u = (int) st.nval;
            st.nextToken(); int v = (int) st.nval;
            adj.get(u).add(v);
            diff[u]++;
            diff[v]--;
        }
        int plus = 0, minus = 0, plusVertex = -1;
        boolean bad = false;
        for (int v = 1; v <= n; v++) {
            if (diff[v] == 1) { plus++; plusVertex = v; }
            else if (diff[v] == -1) minus++;
            else if (diff[v] != 0) bad = true;
        }
        if (bad || ((plus > 0 || minus > 0) && !(plus == 1 && minus == 1 && plusVertex == s))) {
            System.out.println(-1);
            return;
        }
        for (List<Integer> lst : adj) lst.sort(Collections.reverseOrder());
        int[] stack = new int[m + 2];
        int top = 0;
        stack[top++] = s;
        int[] path = new int[m + 2];
        int count = 0;
        while (top > 0) {
            int v = stack[top - 1];
            List<Integer> lst = adj.get(v);
            if (!lst.isEmpty()) stack[top++] = lst.remove(lst.size() - 1);
            else path[count++] = stack[--top];
        }
        if (count != m + 1) { System.out.println(-1); return; }
        StringBuilder sb = new StringBuilder();
        for (int i = count - 1; i >= 0; i--) {
            sb.append(path[i]);
            if (i > 0) sb.append(' ');
        }
        System.out.println(sb);
    }
}

