#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, m, s;
    scanf("%d %d %d", &n, &m, &s);
    vector<vector<int>> adj(n + 1);
    vector<int> diff(n + 1, 0);
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u].push_back(v);
        diff[u]++;
        diff[v]--;
    }
    int plus = 0, minus = 0, plusVertex = -1;
    bool bad = false;
    for (int v = 1; v <= n; v++) {
        if (diff[v] == 1) { plus++; plusVertex = v; }
        else if (diff[v] == -1) minus++;
        else if (diff[v] != 0) bad = true;
    }
    if (bad || ((plus > 0 || minus > 0) && !(plus == 1 && minus == 1 && plusVertex == s))) {
        printf("-1\n");
        return 0;
    }
    for (auto &lst : adj) sort(lst.rbegin(), lst.rend());
    vector<int> stack_, path;
    stack_.push_back(s);
    while (!stack_.empty()) {
        int v = stack_.back();
        if (!adj[v].empty()) {
            stack_.push_back(adj[v].back());
            adj[v].pop_back();
        } else {
            path.push_back(v);
            stack_.pop_back();
        }
    }
    if ((int)path.size() != m + 1) { printf("-1\n"); return 0; }
    reverse(path.begin(), path.end());
    for (size_t i = 0; i < path.size(); i++) printf(i ? " %d" : "%d", path[i]);
    printf("\n");
    return 0;
}
